import * as T from '../vendor/three.module.js';
import {ranchMaterial} from '../tile-materials.js';
// Extracted from the production ranch composer; these are its original primitives.
const mesh=(g,c,role)=>{g.setAttribute('paintPosition',g.attributes.position.clone());const m=new T.Mesh(g,ranchMaterial(c,role));m.castShadow=m.receiveShadow=true;return m;};
export function dressingAsset(kind,size=1){const group=new T.Group();if(kind==='rock'||kind==='shrub'){for(let k=0;k<3;k++){const m=mesh(new T.IcosahedronGeometry((kind==='rock'?.045:.09)*size,0),kind==='rock'?'#94917c':k%2?'#71824b':'#809153','foliage');m.position.set((k-1)*.055,.045+k*.015,0);m.scale.set(1,.8,1);group.add(m);}}else for(let k=0;k<5;k++){const m=mesh(new T.ConeGeometry(.022,.10*size,3),k%2?'#849951':'#9ca65c','groundcover');m.position.set(Math.sin(k*2.4)*.045,.04,Math.cos(k*2.4)*.045);m.rotation.z=(k-2)*.13;group.add(m);}return group;}
export function enclosureAsset(w=20,d=22){const group=new T.Group(),x=w*.1/2,z=d*.1/2,gap=.16;const box=(x,y,z,w,h,d,c)=>{const m=mesh(new T.BoxGeometry(w,h,d),c,'ground');m.position.set(x,y,z);group.add(m);return m;};for(const [a,b]of [[[-x,-z],[x,-z]],[[-x,-z],[-x,z]],[[x,-z],[x,z]],[[-x,z],[-gap,z]],[[gap,z],[x,z]]]){const n=Math.ceil(Math.hypot(b[0]-a[0],b[1]-a[1])/.35);for(let i=0;i<=n;i++)box(a[0]+(b[0]-a[0])*i/n,.085,a[1]+(b[1]-a[1])*i/n,.035,.17,.035,'#ac8962');for(const y of [.065,.13]){const m=box((a[0]+b[0])/2,y,(a[1]+b[1])/2,.025,.025,Math.hypot(b[0]-a[0],b[1]-a[1]),'#b9976e');m.rotation.y=Math.atan2(b[0]-a[0],b[1]-a[1]);}}return group;}
